import{_ as e,c as r,o as p,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"50、【鼎】 巽下离上","description":"周易尚氏学 - 50、【鼎】 巽下离上","frontmatter":{"title":"50、【鼎】 巽下离上","description":"周易尚氏学 - 50、【鼎】 巽下离上"},"headers":[],"relativePath":"zh/classics/shangshi/055.md","filePath":"zh/classics/shangshi/055.md"}'),h={name:"zh/classics/shangshi/055.md"};function s(t,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_50、【鼎】-巽下离上" tabindex="-1">50、【鼎】 巽下离上 <a class="header-anchor" href="#_50、【鼎】-巽下离上" aria-label="Permalink to “50、【鼎】 巽下离上”">​</a></h1><p>元谓五。得位有应。故吉亨。端木国瑚曰。鼎之象不在鼎。而在伏象屯。屯下震为足。互坤为腹。上坎为耳。为铉。凡鼎之象无一不备。后人不知易于正伏象不分。谓下阴为足。中三阳为腹。五阴为耳。易焉有巽足乾腹离耳之象哉。按端木氏说是也。二千年误解。得是而正。其功甚伟。</p><p>彖曰。鼎。象也。以木巽火。亨饪也。圣人亨以享上帝。而大亨以养圣贤。巽而耳目聪明。柔进而上行。得中而应乎刚。是以元亨。</p><p>鼎之用在亨饪。以木巽火。鼎之用也。乾为圣人，高为目。兑为耳。六五为离兑主爻。故耳目聪明。虞翻谓三动成坎离。以坎为耳。后儒多从之。岂知三当位。焉能之不正。任意如此。何象不可得。按易林观之中孚云。鼎炀其耳。以中孚下兑为耳。比之丰云。李耳汇鹊。亦以丰互兑为耳。盖坎之为耳以其陷。兑亦坑坎也。故亦为耳。三爻鼎耳革。五爻鼎黄耳。象甚明也。</p><h3 id="象曰。木上有火。鼎。君子以正位凝命。" tabindex="-1">象曰。木上有火。鼎。君子以正位凝命。 <a class="header-anchor" href="#象曰。木上有火。鼎。君子以正位凝命。" aria-label="Permalink to “象曰。木上有火。鼎。君子以正位凝命。”">​</a></h3><p>鼎偏倚则势危。故贵正。不正则束（左食）覆。鼎敛实于内。故贵凝。不凝则实漫矣。故君子取之。以正位凝命。</p><p>初六。鼎颠趾。利出否。得妾以其子。无咎。</p><p>震为趾。震伏巽陨。故曰颠趾。巽为臭腐。故曰否。否恶也污也。初在下卑污之地。出之四则各当位而利矣。四。兑为妾。四来初是得妾也。初之四体震。震为子。是得妾兼得子也。故利出也。</p><h3 id="象曰。鼎颠趾。未悖也。利出否。以从贵也。" tabindex="-1">象曰。鼎颠趾。未悖也。利出否。以从贵也。 <a class="header-anchor" href="#象曰。鼎颠趾。未悖也。利出否。以从贵也。" aria-label="Permalink to “象曰。鼎颠趾。未悖也。利出否。以从贵也。”">​</a></h3><p>停逆也。初阴顺阳。故曰未悖。初承阳应四。故曰从贵。</p><p>九二。鼎有实。我仇有疾。不我能即。吉。</p><p>乾为实。仇匹也。指五。五乘阳势逆。不能即二，故曰有疾。豫六五乘刚曰贞疾。兹与之同。我谓二。二为三四所隔。既不能即五。五因乘刚有疾。亦不能即二。然我与我仇。究为正应。始虽阻。终必合也。故结之曰吉。象曰终无尤。即谓二五终合也。</p><h3 id="象曰。鼎有实。慎所之也。我仇有疾。终无尤也。" tabindex="-1">象曰。鼎有实。慎所之也。我仇有疾。终无尤也。 <a class="header-anchor" href="#象曰。鼎有实。慎所之也。我仇有疾。终无尤也。" aria-label="Permalink to “象曰。鼎有实。慎所之也。我仇有疾。终无尤也。”">​</a></h3><p>之往也。二前临重阳。行不利。故慎所之。二五终合。故终无尤。按此爻旧解。鲜有当者。一仇字失诂。虞翻谓二据四妇。四为仇。朱子以仇为初。阳遇阳为敌之义。自汉失传。故慎所之三字。皆莫知所谓。清儒以汉为步趋。汉儒误遂无不误矣。</p><p>九三。鼎耳革。其行塞。雉膏不食。方雨亏悔。终吉。</p><p>三至五兑为耳。巽陨落。故曰耳革。行。道也。易林复之中孚云。鼎炀其耳。热不可举。大路壅塞。旅人心苦。以行为道路。盖三承乘皆阳。阳遇阳故其行塞。上离为雉。兑为膏。雉膏在上。乃上不应三。故雉膏不食。兑为雨。为昧。故曰亏悔。亏悔不明也。吴先生云悔晦也。按易林复之云。阴雾作匿。不见白日。不见白日。亏也。于虚赋日月蔽亏。江淹诗金峰各亏日。是也。阴雾作匿晦也。吴读与易林同也。终吉者。初之四则三临重阴。阳得阴则通。故吉。</p><h3 id="象曰。鼎耳革阅失其义也。" tabindex="-1">象曰。鼎耳革阅失其义也。 <a class="header-anchor" href="#象曰。鼎耳革阅失其义也。" aria-label="Permalink to “象曰。鼎耳革阅失其义也。”">​</a></h3><p>义宜也。鼎之用全在耳。今耳革失其用。故曰失义。</p><p>九四。鼎折足，覆公餗，餗其形渥，凶。</p><p>震为足。三至五兑。兑二折震。震象毁。故曰鼎折足。粪为束（左食）。马云键也。郑云菜也。乃三至五巽覆。四为诸候。三公之位。故曰覆公束（左食）。刑屋（右 ）王弼作形渥。古青同通用。管子心术下云。意然后刑。刑然后思。注意感其事。然后呈形。是刑形古通用。兹从各家。京云刑在页（左九）为屋（右 ）。汉书叙传。底剧鼎臣。师古注剧（左屋）厚刑。又周礼秋官司 氏。邦若屋诛。郑注云屋当读为其刑剧之束（左食）。剧（左屋）诛谓不于市也。盖四不当位。故象凶。如是卖束（左食）之象。按易林未济之无妄云。求糜耕田。以无妄互巽为糜。而马氏训束（左食）为健。与易林同。键即糜也。郑氏训为菜。按韩奕之诗曰。其敕（上草）维何。维荀及蒲。疏引易曰鼎折足。覆公敕（上草）。是束（左食）与敕（上草）通用。而郑训与诗合。盖皆巽象。可从。九家云。三公调阴阳。犹鼎之凋五味。足折束（左食）覆。犹三公不胜其任。而覆天子之美。故受此重辜也。王弼以形渥为沾儒。程子谓为汗涩。岂知下系云。德薄而位尊。鲜不及矣。谓及于刑辟也。即读为刑剧（左屋）也。工程所释。皆望文生义。非也。</p><h3 id="覆公餗-信如何也。" tabindex="-1">覆公餗，信如何也。 <a class="header-anchor" href="#覆公餗-信如何也。" aria-label="Permalink to “覆公餗，信如何也。”">​</a></h3><p>乾为信。信如何者。言行为如此。信仰失也。</p><p>六五。鼎黄耳金铉 利贞。</p><p>兑为耳。离黄中。故曰黄耳。乾为金。故曰金铉。铉与扃同。士冠礼设局鼎（上加帽）。郑注扃今文为铉。释文扃鼎扛也。孔疏所谓贯鼎耳而扛之。是也。伏坎象也。六五得中。下有应。故利贞。利贞言二五应也。</p><h3 id="象曰。鼎黄耳。中以为实也" tabindex="-1">象曰。鼎黄耳。中以为实也 <a class="header-anchor" href="#象曰。鼎黄耳。中以为实也" aria-label="Permalink to “象曰。鼎黄耳。中以为实也”">​</a></h3><p>乾为实。九二云。鼎有实。五得中应二。故中以为实。实指二。黄中色。故曰中以为实。</p><p>上九。鼎玉铉。大吉无不利。</p><p>乾为玉。上九阳为直。故象玉铉。又上九以铉举鼎。动作自如。无有滞碍。故大吉无不利。与大畜上九义同。象释曰刚柔节。以五阴为承也。</p><h3 id="象日。玉铉在上。刚柔节也。" tabindex="-1">象日。玉铉在上。刚柔节也。 <a class="header-anchor" href="#象日。玉铉在上。刚柔节也。" aria-label="Permalink to “象日。玉铉在上。刚柔节也。”">​</a></h3><p>上阳得五阴为承。故曰刚柔节。诸家多以三变应上成未济。为刚柔节。岂知六爻独三当位。胡可使其失正。且变而成未济。六爻皆不安。胡能大吉。此自虞翻卦变伎俩。以济其穷者。可复申述之乎。</p>',30)])])}const f=e(h,[["render",s]]);export{_ as __pageData,f as default};
